/*
 * Aurora VM - 解释器实现
 * 支持 500+ 字节码指令的执行
 */

#include "aurora_bytecode.h"

/* 执行 VM 字节码指令 0 */
void vm_exec_000(VMValue* stack, int* sp, VMValue* locals, int* pc) {
    VMValue result;
    result.type = VM_VAL_UNDEFINED;
    result.int_val = 0;
    result.float_val = 0.0;
    result.string_val = NULL;
    result.ptr_val = NULL;
    result.obj = NULL;
    result.ref_count = 1;
    result.hash = 0;
    /* 指令执行逻辑 */
    switch (VM_OP_000) {
        default:
            break;
    }
    stack[++(*sp)] = result;
    (*pc)++;
}

